const { hourlyLimit, requireMarketingConsent } = require('../throttling');
const { deliverVia } = require('../delivery');

const EMAIL_PREVIEW_LENGTH = 90;

function validateEmailRecipient(user) {
  if (!user.email || !user.email.includes('@')) {
    throw new TypeError('user.email is required for email notifications');
  }
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(config, user, message) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${config.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

function formatEmail(envelope, { config, user, message }) {
  const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
  const footer = footerFor(config, user, message);

  return {
    ...envelope,
    to: user.email,
    from: config.from,
    replyTo: config.replyTo,
    subject: `${subjectPrefix}${envelope.title}`,
    text: `${envelope.body}\n\n${footer}`,
    html: `<h1>${escapeHtml(envelope.title)}</h1><p>${escapeHtml(envelope.body)}</p><footer>${escapeHtml(footer)}</footer>`,
    preview: envelope.body.slice(0, EMAIL_PREVIEW_LENGTH)
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const emailChannel = Object.freeze({
  name: 'email',
  defaultMaxPerHour: 8,
  resolveSettings: options => ({
    from: options.from || 'noreply@example.com',
    replyTo: options.replyTo || 'support@example.com',
    unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
  }),
  validateUser: validateEmailRecipient,
  throttleRules: Object.freeze([
    hourlyLimit,
    requireMarketingConsent('emailOptIn', 'user has not opted into marketing email')
  ]),
  format: formatEmail,
  deliver: deliverVia('email', 'email')
});

module.exports = {
  emailChannel
};
const { hourlyLimit, exemptWhen } = require('../throttling');
const { deliverVia } = require('../delivery');

const HOUR_MS = 60 * 60 * 1000;
const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

function validateInAppRecipient(user) {
  if (user.disabledInApp) {
    throw new TypeError('in-app notifications are disabled for this user');
  }
}

function formatInApp(envelope, { config, user, message, options }) {
  const expiresInHours = options.expiresInHours
    || (message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS);
  const expiresAt = new Date(config.now().getTime() + expiresInHours * HOUR_MS);

  return {
    ...envelope,
    userId: user.id,
    icon: message.icon || config.defaultIcon,
    actionUrl: options.actionUrl || message.actionUrl || config.defaultAction,
    read: false,
    expiresAt: expiresAt.toISOString(),
    preview: envelope.title
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const inAppChannel = Object.freeze({
  name: 'inapp',
  defaultMaxPerHour: 50,
  resolveSettings: options => ({
    defaultIcon: options.defaultIcon || 'bell',
    defaultAction: options.defaultAction || '/notifications'
  }),
  validateUser: validateInAppRecipient,
  throttleRules: Object.freeze([
    exemptWhen(({ message }) => message.category === 'security'),
    hourlyLimit
  ]),
  format: formatInApp,
  deliver: deliverVia('inapp', 'in-app')
});

module.exports = {
  inAppChannel
};
const { hourlyLimit, exemptWhen } = require('../throttling');
const { PREVIEW_MAX_LENGTH } = require('../formatting');
const { deliverVia } = require('../delivery');

function validateSlackRecipient(user) {
  if (!user.slackId && !user.slackChannel) {
    throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
  }
}

function blocksFor(envelope, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${envelope.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: envelope.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${envelope.metadata.category}`
        }
      ]
    }
  ];
}

function formatSlack(envelope, { config, user, options }) {
  const channel = options.channel || user.slackChannel || config.defaultChannel;
  const mention = user.slackId ? `<@${user.slackId}> ` : '';
  const text = `${mention}*${envelope.title}*\n${envelope.body}`;

  return {
    ...envelope,
    workspace: user.slackWorkspace || config.defaultWorkspace,
    // Replaces the envelope's `channel: 'slack'` with the Slack channel name.
    channel,
    threadTs: options.threadTs || null,
    text,
    blocks: blocksFor(envelope, mention),
    preview: text.replace(/\*/g, '').slice(0, PREVIEW_MAX_LENGTH)
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const slackChannel = Object.freeze({
  name: 'slack',
  defaultMaxPerHour: 20,
  resolveSettings: options => ({
    defaultWorkspace: options.defaultWorkspace || 'main',
    defaultChannel: options.defaultChannel || '#general'
  }),
  validateUser: validateSlackRecipient,
  throttleRules: Object.freeze([
    exemptWhen(({ options }) => Boolean(options.threadTs)),
    hourlyLimit
  ]),
  format: formatSlack,
  deliver: deliverVia('slack', 'slack')
});

module.exports = {
  slackChannel
};
const { hourlyLimit, requireMarketingConsent } = require('../throttling');
const { deliverVia } = require('../delivery');

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;
const DEFAULT_SEGMENT_LENGTH = 140;

function validateSmsRecipient(user) {
  if (!user.phone || !E164_PATTERN.test(user.phone)) {
    throw new TypeError('user.phone must be E.164 for SMS notifications');
  }
}

// Lengths are UTF-16 code units, so a cut can split a surrogate pair.
function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

function formatSms(envelope, { config, user, message }) {
  const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
  const composed = `${prefix}${envelope.title} - ${envelope.body}`;
  const text = truncate(composed, config.segmentLength);

  return {
    ...envelope,
    to: user.phone,
    from: config.senderId,
    text,
    segments: Math.ceil(text.length / config.segmentLength),
    preview: text
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const smsChannel = Object.freeze({
  name: 'sms',
  defaultMaxPerHour: 4,
  resolveSettings: options => ({
    senderId: options.senderId || 'APP',
    segmentLength: options.segmentLength || DEFAULT_SEGMENT_LENGTH
  }),
  validateUser: validateSmsRecipient,
  throttleRules: Object.freeze([
    hourlyLimit,
    requireMarketingConsent('smsOptIn', 'user has not opted into marketing SMS')
  ]),
  format: formatSms,
  deliver: deliverVia('sms', 'sms')
});

module.exports = {
  smsChannel
};
const { validateRecipient, validateMessage } = require('./validation');
const { evaluateThrottle, throttleKey, recordDelivery } = require('./throttling');
const { applyTemplate, formatEnvelope } = require('./formatting');

const DEFAULT_SENDER = 'Product Team';
const DEFAULT_LOCALE = 'en-US';

/**
 * Settings shared by every channel. Channel strategies add their own fields
 * through `resolveSettings`.
 * @typedef {object} NotifierConfig
 * @property {string} channel
 * @property {object} transport  Map of channel name to `async (payload) => void`.
 * @property {object} templates
 * @property {Map<string, number[]>} throttleStore  Delivery timestamps keyed by `throttleKey`.
 * @property {() => Date} now
 * @property {string} defaultSender
 * @property {string} defaultLocale
 * @property {number} maxPerHour
 */

/**
 * @typedef {object} FormatContext
 * @property {NotifierConfig} config
 * @property {object} user
 * @property {object} message
 * @property {object} options  Per-send options.
 */

/**
 * What a channel contributes to the shared send pipeline.
 * @typedef {object} ChannelStrategy
 * @property {string} name
 * @property {number} defaultMaxPerHour  Used when `options.maxPerHour` is falsy.
 * @property {(options: object) => object} resolveSettings  Channel-specific settings, read from factory options.
 * @property {(user: object) => void} validateUser  Runs after `validateRecipient`; throws TypeError.
 * @property {ReadonlyArray<import('./throttling').ThrottleRule>} throttleRules  Evaluated in order.
 * @property {(envelope: import('./formatting').Envelope, context: FormatContext) => object} format
 * @property {(transport: object, payload: object) => Promise<void>} deliver
 */

/**
 * Builds a notifier for one channel.
 *
 * The returned object doubles as its own config: every step reads settings
 * from it at call time, so reassigning `notifier.transport`, `notifier.now` or
 * `notifier.maxPerHour` affects later sends, as it did with the old class
 * instances. Replacing a method on it does not change what `send` runs.
 *
 * @param {ChannelStrategy} strategy
 * @param {object} [options]
 */
function composeNotifier(strategy, options = {}) {
  const notifier = {
    channel: strategy.name,
    transport: options.transport || {},
    // No channel reads `templates` or `defaultSender`; they stay on the object
    // because callers could read them from the old instances.
    templates: options.templates || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultSender: options.defaultSender || DEFAULT_SENDER,
    defaultLocale: options.defaultLocale || DEFAULT_LOCALE,
    maxPerHour: options.maxPerHour || strategy.defaultMaxPerHour,
    ...strategy.resolveSettings(options)
  };

  function validateUser(user) {
    validateRecipient(user);
    strategy.validateUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    return evaluateThrottle(strategy.throttleRules, { config: notifier, user, message, options: sendOptions });
  }

  function format(user, message, sendOptions = {}) {
    const envelope = formatEnvelope(notifier, user, message, sendOptions);
    return strategy.format(envelope, { config: notifier, user, message, options: sendOptions });
  }

  function deliver(payload) {
    return strategy.deliver(notifier.transport, payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel: notifier.channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const payload = format(user, message, sendOptions);
    await deliver(payload);
    recordDelivery(notifier, user, message);

    return {
      channel: notifier.channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return Object.assign(notifier, {
    send,
    validateUser,
    validateMessage,
    shouldThrottle,
    throttleKey: (user, message) => throttleKey(notifier, user, message),
    format,
    applyTemplate,
    recordDelivery: (user, message) => recordDelivery(notifier, user, message),
    deliver
  });
}

module.exports = {
  composeNotifier
};
/**
 * Creates a deliver step that hands the payload to `transport[transportKey]`.
 * @param {string} transportKey  Property on the transport object, e.g. 'inapp'.
 * @param {string} label  Channel name used in the error message, e.g. 'in-app'.
 * @returns {(transport: object, payload: object) => Promise<void>}
 */
function deliverVia(transportKey, label) {
  return async function deliver(transport, payload) {
    if (typeof transport[transportKey] !== 'function') {
      throw new Error(`${label} transport is not configured`);
    }
    // Called as a method so transports that rely on `this` keep working.
    await transport[transportKey](payload);
  };
}

module.exports = {
  deliverVia
};
/** Default cap on `preview` length; channels may shorten it further. */
const PREVIEW_MAX_LENGTH = 120;

/**
 * @typedef {object} Envelope
 * @property {string} id
 * @property {string} channel
 * @property {string} locale
 * @property {string} title
 * @property {string} body
 * @property {string} preview
 * @property {{ category: string, priority: string, generatedAt: string }} metadata
 */

/**
 * Replaces `{{name}}`, `{{id}}` and `{{category}}` placeholders.
 * @param {unknown} value  Coerced with String().
 * @param {{ id: unknown, name?: string }} user
 * @param {{ category?: string }} message
 * @returns {string}
 */
function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Builds the fields every channel payload starts from.
 * @param {import('./composeNotifier').NotifierConfig} config
 * @param {object} user
 * @param {object} message
 * @param {object} options  Per-send options.
 * @returns {Envelope}
 */
function formatEnvelope(config, user, message, options) {
  const id = `${config.channel}-${user.id}-${config.now().getTime()}`;
  const locale = options.locale || user.locale || config.defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel: config.channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_MAX_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: config.now().toISOString()
    }
  };
}

module.exports = {
  PREVIEW_MAX_LENGTH,
  applyTemplate,
  formatEnvelope
};
const { composeNotifier } = require('./composeNotifier');
const { emailChannel } = require('./channels/email');
const { smsChannel } = require('./channels/sms');
const { slackChannel } = require('./channels/slack');
const { inAppChannel } = require('./channels/inapp');

function notifierFactory(strategy) {
  // A regular function, not an arrow: registry entries used to be classes, and
  // `new registry.email(options)` still returns the composed notifier this way.
  return function createChannelNotifier(options) {
    return composeNotifier(strategy, options);
  };
}

/** Channel name to notifier factory. */
const registry = {
  email: notifierFactory(emailChannel),
  sms: notifierFactory(smsChannel),
  slack: notifierFactory(slackChannel),
  inapp: notifierFactory(inAppChannel)
};

/**
 * @param {string} channel  One of the `registry` keys.
 * @param {object} [options]
 * @throws {TypeError} for a channel that is not an own key of `registry`
 */
function createNotifier(channel, options = {}) {
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

/**
 * Creates one notifier per registered channel, all built from the same options.
 * @param {object} [options]
 * @returns {Record<string, ReturnType<typeof createNotifier>>}
 */
function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
/**
 * Checks every channel applies before its own recipient rules.
 * @param {unknown} user
 * @throws {TypeError} when user is not an object or has no id
 */
function validateRecipient(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

/**
 * @param {unknown} message
 * @throws {TypeError} when message is not an object or lacks a title or body
 */
function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

module.exports = {
  validateRecipient,
  validateMessage
};
# Notifications

Sends one message to one user over email, SMS, Slack or an in-app inbox. Each
channel validates the recipient, applies throttling, formats a payload and passes
it to a transport function you supply.

## Usage

```js
const { createNotifier, createAllNotifiers, registry } = require('./src/notifications');

const email = createNotifier('email', {
  transport: { email: async payload => mailer.send(payload) },
  from: 'alerts@example.com'
});

await email.send(
  { id: 'u1', name: 'Ava', email: 'ava@example.com' },
  { title: 'Hello {{name}}', body: 'Your report is ready', category: 'transactional' }
);
// { channel: 'email', status: 'sent', userId: 'u1', id: 'email-u1-<ms>', preview: 'Your report is ready' }

await email.send(
  { id: 'u1', email: 'ava@example.com' },
  { title: 'Sale', body: '20% off', category: 'marketing' }
);
// { channel: 'email', status: 'throttled', reason: 'user has not opted into marketing email', retryAt: null, userId: 'u1' }
```

`createAllNotifiers(options)` returns `{ email, sms, slack, inapp }`, all built
from the same options. `registry` maps each channel name to its factory.

`send(user, message, options)` rejects with a `TypeError` for invalid input,
with `Error('<channel> transport is not configured')` when the transport has no
function for the channel, and with the transport's own error when delivery
fails. A throttled message resolves with `status: 'throttled'` and is not
delivered.

## Layout

| File | Responsibility |
| --- | --- |
| `index.js` | Public API: `createNotifier`, `createAllNotifiers`, `registry` |
| `composeNotifier.js` | Builds a notifier from a channel strategy and runs the send pipeline |
| `validation.js` | Recipient and message checks shared by every channel |
| `throttling.js` | Hourly limit, exemption and consent rules, plus the delivery record |
| `formatting.js` | Placeholder substitution and the envelope every payload starts from |
| `delivery.js` | Hands a payload to `transport[<channel>]` |
| `channels/*.js` | One strategy per channel |

## How `send` runs

1. `validateRecipient(user)`, then the channel's `validateUser(user)`.
2. `validateMessage(message)`.
3. The channel's throttle rules, in order. A throttled verdict returns early.
4. `formatEnvelope` builds the shared fields (`id`, `locale`, `title`, `body`,
   `preview`, `metadata`), then the channel's `format` adds its own.
5. The channel's `deliver` awaits the transport.
6. `recordDelivery` stores the send time for the hourly limit.

A delivery is recorded only after the transport resolves, so a failed delivery
does not count against the limit.

## Channel strategies

A strategy is a frozen object:

```js
{
  name: 'sms',
  defaultMaxPerHour: 4,
  resolveSettings: options => ({ senderId: options.senderId || 'APP', ... }),
  validateUser: user => { /* throw TypeError */ },
  throttleRules: [hourlyLimit, requireMarketingConsent('smsOptIn', '...')],
  format: (envelope, { config, user, message, options }) => ({ ...envelope, ... }),
  deliver: deliverVia('sms', 'sms')
}
```

Settings and defaults. Every default is applied with `||`, so `0` and `''`
fall back to it.

| Scope | Setting (default) |
| --- | --- |
| All channels | `transport` (`{}`), `throttleStore` (new `Map` per notifier), `now` (`() => new Date()`), `defaultLocale` (`'en-US'`), `defaultSender` (`'Product Team'`), `templates` (`{}`), `maxPerHour` (channel default below) |
| email, max 8/h | `from` (`noreply@example.com`), `replyTo` (`support@example.com`), `unsubscribeBaseUrl` (`https://example.com/unsubscribe`) |
| sms, max 4/h | `senderId` (`APP`), `segmentLength` (`140`) |
| slack, max 20/h | `defaultWorkspace` (`main`), `defaultChannel` (`#general`) |
| inapp, max 50/h | `defaultIcon` (`bell`), `defaultAction` (`/notifications`) |

Throttle rules per channel. A rule returns a verdict to stop evaluation or `null`
to pass to the next one. If every rule passes, the message is sent.

| Channel | Rules |
| --- | --- |
| email | `hourlyLimit`, then `requireMarketingConsent('emailOptIn')` |
| sms | `hourlyLimit`, then `requireMarketingConsent('smsOptIn')` |
| slack | `exemptWhen(options.threadTs)`, then `hourlyLimit` |
| inapp | `exemptWhen(message.category === 'security')`, then `hourlyLimit` |

`hourlyLimit` counts sends per channel, user id and category over a sliding hour.
It skips `force: true` and `priority: 'urgent'` sends. Because the consent rule
comes after it, an urgent or forced marketing message still needs opt-in.

## Design decisions

**Strategies instead of subclasses.** The old subclasses changed behavior by
wrapping `super` calls, and each wrapped them differently: email and SMS called
`super.shouldThrottle()` first and then checked consent; Slack and in-app
returned early and never called it. You had to read two files to know which
checks ran and in what order. Now each channel lists its rules, and the
pipeline in `composeNotifier.js` is the only code that sequences the steps.

**Throttling as a rule list.** A list shows the order in one place, and the
shared rules (`hourlyLimit`, `exemptWhen`, `requireMarketingConsent`) are small
functions that can be tested alone. Email and SMS share one consent rule that
takes the opt-in field and reason as parameters.

**The notifier object is also its config.** `composeNotifier` puts the settings
on the returned object, and the pipeline reads them at call time. Code that
reassigns `notifier.transport`, `notifier.now` or `notifier.maxPerHour` after
creation behaves as it did with the class instances.

**Registry entries are regular functions.** They used to be classes, so callers
could write `new registry.email(options)`. A regular function that returns an
object still works with `new`, and it can be called without `new`.

## Compatibility with the class-based version

Kept the same:

- The `index.js` exports and the `registry` keys.
- `send` results, payload fields and key order, error types and messages, and
  when errors occur (rejections from `send`, not synchronous throws).
- The data properties on each notifier, in the same order, with the same
  defaults.
- The stage methods `validateUser`, `validateMessage`, `shouldThrottle`,
  `throttleKey`, `format`, `applyTemplate`, `recordDelivery` and `deliver`.
- The number and order of `now()` calls per send, so injected clocks see the
  same sequence.
- Transport functions are still called as methods (`transport.email(payload)`),
  so `this` inside them is the transport object.

Changed:

- Replacing a method on a notifier (for example `notifier.format = fn`) no
  longer changes what `send` does. To customize a channel, change or add a
  strategy.
- The subclass helpers `escapeHtml`, `footerFor`, `truncate` and `blocksFor` are
  now private to their channel modules and are not notifier methods.
- `instanceof` checks against the old classes are gone with the classes.
- `createNotifier` only accepts own keys of `registry`. Before, inherited names
  reached `Object.prototype`: `'constructor'` returned the options object and
  `'toString'` threw "is not a constructor". Now they throw
  `unknown notification channel`, like any other unknown name.

## Existing behavior this refactor keeps

These behaviors predate the refactor. They are left as-is because changing
them would change results:

- The throttle store is never pruned. Keys and timestamps accumulate for the
  life of the store, so a long-running process should pass its own
  `throttleStore` and clear it.
- Concurrent sends to the same key can exceed `maxPerHour`: each passes the
  check before any of them records a delivery.
- SMS truncation counts UTF-16 code units, so it can split an emoji or other
  surrogate pair. `segments` is computed after truncation, so it is always 1.
- `templates` and `defaultSender` are stored but not used by any channel.

## Adding a channel

1. Add `channels/<name>.js` exporting a frozen strategy with the shape above.
   Use `deliverVia('<transportKey>', '<label>')` for delivery.
2. Register it in `index.js`: `<name>: notifierFactory(<name>Channel)`.

