const { hourlyLimit } = require('../throttling');
const { deliverVia } = require('../delivery');

function validateWebhookRecipient(user) {
  if (typeof user.webhookUrl !== 'string' || !user.webhookUrl.startsWith('https://')) {
    throw new TypeError('user.webhookUrl must be an https:// URL for webhook notifications');
  }
}

function formatWebhook(envelope, { user, message }) {
  return {
    ...envelope,
    url: user.webhookUrl,
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    json: JSON.stringify({
      title: envelope.title,
      body: envelope.body,
      category: message.category || 'general',
      userId: user.id
    })
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const webhookChannel = Object.freeze({
  name: 'webhook',
  defaultMaxPerHour: 10,
  resolveSettings: () => ({}),
  validateUser: validateWebhookRecipient,
  throttleRules: Object.freeze([hourlyLimit]),
  format: formatWebhook,
  deliver: deliverVia('webhook', 'webhook')
});

module.exports = {
  webhookChannel
};
EOF
